#!/bin/bash
set -eo pipefail
/data1/home/sunyiq/kalmannet_original_noise_multiday_evaluation_20261008_recovery3/runtime/venv/bin/python -X utf8 -B - <<'DEPLOY_STATE'

import base64,hashlib,io,json,shutil,subprocess,sys,tarfile
from pathlib import Path
NEW=Path('/data1/home/sunyiq/kalmannet_original_noise_internal_state_diagnosis_20261011')
def digest(p):
    h=hashlib.sha256()
    with p.open('rb') as f:
        for b in iter(lambda:f.read(1048576),b''):h.update(b)
    return h.hexdigest()
def verify(root,item,name):
    p=(root/name).resolve()
    if not p.is_relative_to(root.resolve()) or p.is_symlink() or p.stat().st_size!=item['bytes'] or digest(p)!=item['sha256']:
        raise RuntimeError('Frozen deployment file differs: '+str(p))
    return p
if NEW.exists() or NEW.is_symlink():raise RuntimeError('Existing isolated root preserved; never redeploy')
data=base64.b64decode('',validate=True)
if hashlib.sha256(data).hexdigest()!='d5ec30715a1251e8026b6f4ed18d6388faed29c598447126408106d9fcaae30d':raise RuntimeError('Overlay differs')
files={}
with tarfile.open(fileobj=io.BytesIO(data),mode='r:gz') as archive:
    for m in archive.getmembers():
        p=Path(m.name)
        if not m.isfile() or p.is_absolute() or '..' in p.parts or m.name in files:raise RuntimeError('Unsafe overlay member')
        files[m.name]=archive.extractfile(m).read()
manifest_data=files['package_manifest.json']
if hashlib.sha256(manifest_data).hexdigest()!='a32ccbfd9a4941ac5a670931c53a1c03d58fca482bd723d11f75d3653d34b454':raise RuntimeError('Package manifest differs')
manifest=json.loads(manifest_data)
review_data=files['results/review/source_review.json']
review=json.loads(review_data)
if (hashlib.sha256(review_data).hexdigest()!='82953432443e3fa048c04d515db04705439b192bfff6c985a94fdb99c2a05f0b' or review['status']!='PASS' or review['manifest_sha256']!='a32ccbfd9a4941ac5a670931c53a1c03d58fca482bd723d11f75d3653d34b454' or review['contract_sha256']!='ffb3178c091d0abbbbb89617ac89936c6ff754b94468e513aa54fe7d97b04e89'):
    raise RuntimeError('Independent reviewed identity differs')
old=Path(manifest['old_remote_root'])
for item in manifest['verified_remote_copies']:verify(old,item,item['old_path'])
contract=json.loads(files['results/control/contract.json'])
if hashlib.sha256(files['results/control/contract.json']).hexdigest()!='ffb3178c091d0abbbbb89617ac89936c6ff754b94468e513aa54fe7d97b04e89':raise RuntimeError('Contract bytes differ')
if contract['remote_root']!=str(NEW):raise RuntimeError('Root binding differs')
NEW.mkdir()
for name in ('code','results/control','results/review/accepted','submissions','logs','tmp'):(NEW/name).mkdir(parents=True,exist_ok=True)
for item in manifest['verified_remote_copies']:
    dst=NEW/item['new_path']
    dst.parent.mkdir(parents=True,exist_ok=True)
    with dst.open('xb') as out,(old/item['old_path']).open('rb') as src:shutil.copyfileobj(src,out)
for name,data in files.items():
    dst=NEW/name
    dst.parent.mkdir(parents=True,exist_ok=True)
    with dst.open('xb') as out:out.write(data)
for item in manifest['files']:verify(NEW,item,item['path'])
for item in manifest['verified_remote_copies']:verify(old,item,item['old_path'])
completed=subprocess.run([sys.executable,'-X','utf8','-B',str(NEW/'code/remote_state.py'),'check'],capture_output=True,text=True,timeout=180,check=True)
result={'status':'DEPLOYED_VERIFIED_NO_SCIENTIFIC_SUBMISSION','remote_root':str(NEW),'contract_sha256':'ffb3178c091d0abbbbb89617ac89936c6ff754b94468e513aa54fe7d97b04e89','manifest_sha256':'a32ccbfd9a4941ac5a670931c53a1c03d58fca482bd723d11f75d3653d34b454','source_review_sha256':'82953432443e3fa048c04d515db04705439b192bfff6c985a94fdb99c2a05f0b','old_files_verified_unchanged':len(manifest['verified_remote_copies']),'check_stdout':completed.stdout,'scientific_jobs_submitted':0}
with (NEW/'results/control/deployment_identity.json').open('x',encoding='utf-8') as h:json.dump(result,h,indent=2)
print('DEPLOYMENT_JSON='+json.dumps(result),flush=True)

DEPLOY_STATE
